import zipfile, re
p='seed_collection_0070_template_7232_input.xlsx'
z=zipfile.ZipFile(p)
data=z.read('xl/worksheets/sheet1.xml').decode('utf-8')
# parse row/c cell elements in sheetData
cells = re.findall(r'<c r="([A-Z]+\d+)"([^>]*)>([^<]*)</c>', data)
# maybe self-closing cells
cells_self = re.findall(r'<c r="([A-Z]+\d+)"([^>]*)/>', data)
print('num cells with children', len(cells), 'self-closing', len(cells_self))
# print cells in B5:J42 that have t="n" no v, no f
for ref, attrs, inner in cells:
    col=re.match(r'[A-Z]+',ref).group(); row=int(re.match(r'\d+',ref).group())
    if 5<=row<=42 and 'B'<=col<='J':
        if 't="n"' in attrs and '<f>' not in inner and '<v>' not in inner:
            pass
# count all cells in range by type
count_n_empty=0; count_str_empty=0; count_with_v=0; count_f=0; count_absent=0
for ref, attrs, inner in cells:
    col=re.match(r'[A-Z]+',ref).group(); row=int(re.match(r'\d+',ref).group())
    if 5<=row<=42 and 'B'<=col<='J':
        if '<f>' in inner:
            count_f+=1
        elif '<v>' in inner:
            count_with_v+=1
        elif 't="n"' in attrs:
            count_n_empty+=1
        elif 't="str"' in attrs or 't="inlineStr"' in attrs:
            count_str_empty+=1
        else:
            count_absent+=1
print('in B5:J42 with children: f',count_f,'v',count_with_v,'n_empty',count_n_empty,'str_empty',count_str_empty,'other',count_absent)
